use genewars_runtime::creature_world::{find_common_idle_relocation,CreatureError};
fn main(){let b=std::fs::read(std::env::args().nth(1).unwrap()).unwrap();let mut at=0;let mut cases=0;
while at<b.len(){let word=|n|i16::from_le_bytes(b[n..n+2].try_into().unwrap());let point=[word(at),word(at+2)];let threshold=word(at+4)as u16;let count=word(at+6)as u16;let found=b[at+8]!=0;let expected=[word(at+9),word(at+11)];at+=13;let mut actual=Vec::new();let result=find_common_idle_relocation(point,|p|{actual.push(p);Ok(actual.len()-1>=usize::from(threshold))}).unwrap();assert_eq!(result,if found{Some(expected)}else{None});assert_eq!(actual.len(),usize::from(count));for p in actual{assert_eq!(p,[word(at),word(at+2)],"case{cases} threshold{threshold} byte{at}");at+=4;}cases+=1;}
let mut calls=0;assert!(find_common_idle_relocation([0,0],|_|{calls+=1;Err(CreatureError::MotionEnvironment)}).is_err());assert_eq!(calls,1);println!("{cases} literal search cases and callback rejection verified");}
